// client/src/Welcome.js
import React, { useEffect, useRef, useState } from "react";
import { gsap } from "gsap";
import "./Welcome.css";


export default function Welcome() {
  const titleRef = useRef(null);
  const subRef = useRef(null);
  const btnRef = useRef(null);
  const fallingRef = useRef(null);
  const [message, setMessage] = useState("");

  // sample images (put these under client/public/screenshots/)
  const SAMPLE_IMAGES = [
    "/screenshots/ss1.png",
    "/screenshots/ss2.png",
    "/screenshots/ss3.png",
    "/screenshots/ss4.png",
  ];

  // falling images spawn
  useEffect(() => {
    console.log("Welcome: mounting falling images");
    const container = fallingRef.current;
    if (!container) return;

    container.innerHTML = "";
    const items = [];
    const COUNT = 9;

    function spawn(i) {
      const img = document.createElement("img");
      img.className = "falling-img";
      img.src = SAMPLE_IMAGES[i % SAMPLE_IMAGES.length];
      img.alt = "screenshot";
      container.appendChild(img);

      // initial set
      const startX = Math.random() * 100;
      const scale = 0.6 + Math.random() * 0.6;
      const rot = -25 + Math.random() * 50;
      gsap.set(img, { xPercent: startX, y: -150 - Math.random() * 200, scale, rotation: rot, opacity: 0.95 });

      const duration = 7 + Math.random() * 6;
      const delay = Math.random() * 3;

      const tween = gsap.to(img, {
        y: window.innerHeight + 300,
        rotation: rot + (Math.random() > 0.5 ? 60 : -60),
        duration,
        delay,
        ease: "none",
        repeat: -1,
        repeatDelay: 1 + Math.random() * 2,
        onRepeat: () => {
          gsap.set(img, { xPercent: Math.random() * 100, y: -150 });
        },
      });

      items.push({ img, tween });
    }

    for (let i = 0; i < COUNT; i++) spawn(i);

    return () => {
      items.forEach((it) => {
        try {
          it.tween.kill();
          it.img.remove();
        } catch (e) {}
      });
    };
  }, []); // run once

  // title/sub/button animation
  useEffect(() => {
    console.log("Welcome: starting GSAP intro");
    const a = titleRef.current, b = subRef.current, c = btnRef.current;
    // guard
    if (!a || !b || !c) {
      console.warn("Welcome: refs missing", { a, b, c });
      return;
    }

    const tl = gsap.timeline();
    gsap.set([a, b, c], { opacity: 0, y: 20 });
    tl.to(a, { opacity: 1, y: 0, duration: 0.7, ease: "power3.out" });
    tl.to(b, { opacity: 1, y: 0, duration: 0.5, ease: "power3.out" }, "-=0.3");
    tl.to(c, { opacity: 1, y: 0, duration: 0.45, ease: "back.out(1.2)" }, "-=0.25");
    gsap.to(c, { scale: 1.03, duration: 1.2, yoyo: true, repeat: -1, ease: "sine.inOut", delay: 0.6 });

    return () => {
      tl.kill();
    };
  }, []);

  // click -> try electron IPC, else show message
  async function handleClick() {
    // small click animation
    gsap.fromTo(btnRef.current, { scale: 1 }, { scale: 0.95, duration: 0.06, yoyo: true, repeat: 1, ease: "power1.inOut" });

    // If running in Electron, open python app via IPC
    if (window?.electronAPI?.openPythonApp) {
      setMessage("Launching desktop application...");
      try {
        const res = await window.electronAPI.openPythonApp({ args: [] });
        console.log("openPythonApp result:", res);
        setMessage("Desktop launched (check native window).");
      } catch (err) {
        console.error("Failed to open Python app:", err);
        setMessage("Failed to launch desktop app. See logs.");
      }
      return;
    }

    // Browser fallback (friendly)
    setMessage("Not running inside Electron. To open the Python app, run the Electron dev flow (see README).");
    // optionally show instructions or a link to docs here
  }

  return (
    <div className="welcome-mini-root">
      <div className="falling-back" ref={fallingRef} aria-hidden="true" />

      <div className="center-stage">
        <h1 className="wm-title" ref={titleRef}>
          Welcome to Visual Memory Search
        </h1>

        <h2 className="wm-sub" ref={subRef}>
          - Smart Screenshot Search Engine
        </h2>

        <button
          className="wm-cta"
          ref={btnRef}
          onClick={handleClick}
          aria-label="Search Screenshots"
          title="Search Screenshots"
        >
          Search Screenshots
        </button>

        {message && <div style={{ marginTop: 14, color: "#cfe2ff", opacity: 0.95 }}>{message}</div>}
      </div>
    </div>
  );
}
